-- UST Campus Store case study (CSELEC1C). Practice data, not real sales.
\set ON_ERROR_STOP on
SET client_min_messages = warning;
-- Session 2, step 1 (CDC with a change log).
-- From May 8 to 14 the POS vendor sent a change log instead of table access.
-- These changes are NOT in src.sales. You must apply them from the log.
-- op: I = insert, U = update (full new row), D = delete (key only).

BEGIN;
DROP TABLE IF EXISTS src.sales_change_log;
CREATE TABLE src.sales_change_log (
    lsn text,
    xid text,
    op text,
    committed_at text,
    receipt_no text,
    line_no text,
    sold_at text,
    branch_code text,
    product_code text,
    customer_id text,
    txn_type text,
    quantity text,
    unit_price text,
    discount text,
    line_total text,
    payment_method text
);
COPY src.sales_change_log (lsn, xid, op, committed_at, receipt_no, line_no, sold_at, branch_code, product_code, customer_id, txn_type, quantity, unit_price, discount, line_total, payment_method) FROM stdin WITH (FORMAT csv);
